package de.sebaro_ventures.design.designsystem

import androidx.compose.animation.EnterTransition
import androidx.compose.animation.core.tween
import androidx.compose.animation.fadeIn
import androidx.compose.animation.slideInVertically
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalDensity
import de.sebaro_ventures.design.SebaroTheme

/**
 * D46 (4): how new content enters. Use as AnimatedVisibility(visible, enter = sbEnter()). From below over
 * x.enterDistance in motion.durationLong with the emphasized easing; with sbReduceMotion() only a fade over
 * x.enterFadeDuration (200 ms, D102 (52)). Android limit: under the system's „Remove animations“ the window scales
 * every transition to 0, so the fade ends in its first frame there (spec/03 §13.1); under the app setting it lasts 200 ms.
 */
@Composable
fun sbEnter(): EnterTransition {
    val t = SebaroTheme.tokens
    val fade = fadeIn(tween(t.x.enterFadeDuration, easing = t.motion.easingStandard))
    if (sbReduceMotion()) return fade
    val distance = with(LocalDensity.current) { t.x.enterDistance.roundToPx() }
    return fadeIn(tween(t.motion.durationLong, easing = t.motion.easingEmphasized)) +
        slideInVertically(tween(t.motion.durationLong, easing = t.motion.easingEmphasized)) { distance }
}
